// ===== MARKET HOURS FILTER =====

const now = new Date();

const istTime = new Date(
  now.toLocaleString("en-US", {
    timeZone: "Asia/Kolkata"
  })
);

const hour = istTime.getHours();
const minutes = istTime.getMinutes();

// NSE/BSE: 9:15 AM → 3:30 PM

const isMarketOpen =
(
  (hour > 9 || (hour === 9 && minutes >= 15))
  &&
  (hour < 15 || (hour === 15 && minutes <= 30))
);

if (!isMarketOpen) {

  console.log("Market Closed");

  return [];
}

// ===== FETCH NEWS =====

const news = $json.data.latest_news || [];

// Important categories

const importantSubCategories = [
  "operational-updates",
  "strategic-partnerships",
  "legal-compliance",
  "product-launches-innovation",
  "management-leadership"
];

// Important keywords

const importantKeywords = [
  "contract",
  "order",
  "partnership",
  "acquisition",
  "merger",
  "expansion",
  "investment",
  "government",
  "approval",
  "launch",
  "compliance",
  "fraud",
  "penalty",
  "warning",
  "shutdown",
  "capacity",
  "deal",
  "mou",
  "growth"
];

// Ignore boring news

const ignorePatterns = [
  "board meeting",
  "earnings call",
  "financial results",
  "conference call",
  "audited results"
];

const filteredNews = news
.filter(item => {

  const title =
    item.news_object?.title?.toLowerCase() || "";

  const text =
    item.news_object?.text?.toLowerCase() || "";

  const subCategory =
    item.sub_category || "";

  const importantCategory =
    importantSubCategories.includes(subCategory);

  const keywordMatch =
    importantKeywords.some(keyword =>
      title.includes(keyword) ||
      text.includes(keyword)
    );

  const isIgnored =
    ignorePatterns.some(pattern =>
      title.includes(pattern) ||
      text.includes(pattern)
    );

  return (importantCategory || keywordMatch) && !isIgnored;
})

.map(item => {

  return {
    json: {

      title:
        item.news_object?.title || "",

      description:
        item.news_object?.text || "",

      short_description:
        (item.news_object?.text || "").slice(0, 250),

      sentiment:
        item.news_object?.overall_sentiment || "neutral",

      category:
        item.category || "",

      sub_category:
        item.sub_category || "",

      stock_name:
        item.stock_name || "",

      symbol:
        item.sm_symbol || "",

      market_cap:
        item.metadata?.marketcap || "",

      sector:
        item.metadata?.sector_name || "",

      publish_date:
        item.publish_date || "",

      article_id:
        item.article_id || "",

      article_slug:
        item.article_slug || "",

      impact_score:
        item.news_object?.overall_sentiment === "positive"
          ? 8
          : item.news_object?.overall_sentiment === "negative"
          ? 7
          : 5
    }
  };
});

return filteredNews;

